import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import {createHash} from 'node:crypto';
test('offline SNES runtime files and license sources match pinned bundle manifest',()=>{const root=new URL('../public/retro/emulator/',import.meta.url),manifest=JSON.parse(fs.readFileSync(new URL('manifest.json',root)));for(const [name,hash]of Object.entries(manifest.files)){const bytes=fs.readFileSync(new URL(name,root));assert.equal(createHash('sha256').update(bytes).digest('hex'),hash,name);}for(const file of ['data/loader.js','data/emulator.min.js','data/emulator.min.css','data/cores/snes9x-wasm.data','data/cores/snes9x-legacy-wasm.data','data/compression/extract7z.js','LICENSE-EmulatorJS.txt','LICENSE-Snes9x.txt'])assert.ok(manifest.files[file],file);});
